SELECT  FROM t_service_sku
WHERE service_level = #{serviceLevel} AND service_mode = #{serviceMode}
  AND status = 1 AND deleted_at IS NULL LIMIT 1

SELECT  FROM t_service_sku

    deleted_at IS NULL
    AND service_mode = #{serviceMode}
    AND status = #{status}

ORDER BY service_level ASC, id ASC
LIMIT #{offset}, #{limit}
